-- Entasis Academy, migration 9 : schemas et figures des decks (brouillons).
--
-- Genere par scripts/academy/generer-decks.mjs depuis scripts/academy/decks/*.json :
-- ne pas editer a la main, regenerer. Complete le brouillon courant d un
-- module deja seme par la migration 7 : pose les schemas de la version
-- (remplacement par cle, les autres cles conservees), pose payload.figure
-- sur les exercices existants reperes par (ordre, type) qui n en ont pas
-- encore, insere les exercices nouveaux (ordre au dela du maximum existant)
-- avec leur corrige, ordre et association deja melanges. Idempotent. Une
-- version publiee n est jamais touchee : sans brouillon, raise notice et
-- rien. A appliquer apres la migration 8 (colonne academy_module_versions.schemas).

-- ── Schemas : Réussir la découverte client (reussir-la-decouverte) ──
do $schemas_reussir_la_decouverte$
declare v_mod uuid; v_ver uuid; v_max integer; v_item uuid; v_nouveaux jsonb; v_conserves jsonb;
begin
  select id into v_mod from public.academy_modules where slug = $academy_deck$reussir-la-decouverte$academy_deck$;
  if v_mod is null then
    raise notice 'academy_9_schemas : module % absent, rien a faire (semer la migration 7 d abord)', $academy_deck$reussir-la-decouverte$academy_deck$;
    return;
  end if;
  select id into v_ver from public.academy_module_versions where module_id = v_mod and statut = 'brouillon' order by numero desc limit 1;
  if v_ver is null then
    raise notice 'academy_9_schemas : aucun brouillon pour %, rien a faire (une version publiee ne se modifie pas)', $academy_deck$reussir-la-decouverte$academy_deck$;
    return;
  end if;
  -- Schemas de la version : les cles du deck remplacent les leurs, les autres restent.
  v_nouveaux := $academy_deck$[{"cle":"trois_poches","titre":"Les trois poches de l’épargne, dans l’ordre","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 640 360\" font-family=\"system-ui, -apple-system, Segoe UI, sans-serif\"><title>Les trois poches de l’épargne, dans l’ordre</title><rect x=\"0\" y=\"0\" width=\"640\" height=\"360\" fill=\"#FFFFFF\"/><text x=\"320\" y=\"34\" text-anchor=\"middle\" font-size=\"20\" font-weight=\"700\" fill=\"#162443\">Les trois poches de l’épargne, dans l’ordre</text><text x=\"320\" y=\"58\" text-anchor=\"middle\" font-size=\"14\" fill=\"#8A95A8\">Une somme à placer : on remplit une poche avant de passer à la suivante</text><rect x=\"30\" y=\"88\" width=\"180\" height=\"162\" rx=\"8\" fill=\"#F5EDD8\" stroke=\"#162443\" stroke-width=\"2\"/><rect x=\"230\" y=\"88\" width=\"180\" height=\"162\" rx=\"8\" fill=\"#F5EDD8\" stroke=\"#162443\" stroke-width=\"2\"/><rect x=\"430\" y=\"88\" width=\"180\" height=\"162\" rx=\"8\" fill=\"#F5EDD8\" stroke=\"#162443\" stroke-width=\"2\"/><circle cx=\"120\" cy=\"88\" r=\"18\" fill=\"#162443\"/><circle cx=\"320\" cy=\"88\" r=\"18\" fill=\"#162443\"/><circle cx=\"520\" cy=\"88\" r=\"18\" fill=\"#162443\"/><text x=\"120\" y=\"95\" text-anchor=\"middle\" font-size=\"18\" font-weight=\"700\" fill=\"#FFFFFF\">1</text><text x=\"320\" y=\"95\" text-anchor=\"middle\" font-size=\"18\" font-weight=\"700\" fill=\"#FFFFFF\">2</text><text x=\"520\" y=\"95\" text-anchor=\"middle\" font-size=\"18\" font-weight=\"700\" fill=\"#FFFFFF\">3</text><text x=\"120\" y=\"130\" text-anchor=\"middle\" font-size=\"18\" font-weight=\"700\" fill=\"#162443\">Précaution</text><text x=\"320\" y=\"130\" text-anchor=\"middle\" font-size=\"18\" font-weight=\"700\" fill=\"#162443\">Projets datés</text><text x=\"520\" y=\"130\" text-anchor=\"middle\" font-size=\"18\" font-weight=\"700\" fill=\"#162443\">Long terme</text><text x=\"120\" y=\"158\" text-anchor=\"middle\" font-size=\"15\" font-weight=\"700\" fill=\"#2C3548\">Disponible et sûre</text><text x=\"120\" y=\"182\" text-anchor=\"middle\" font-size=\"14\" fill=\"#2C3548\">Repère AMF :</text><text x=\"120\" y=\"204\" text-anchor=\"middle\" font-size=\"14\" fill=\"#2C3548\">2 à 6 mois de revenus</text><text x=\"320\" y=\"158\" text-anchor=\"middle\" font-size=\"15\" font-weight=\"700\" fill=\"#2C3548\">Une date par projet</text><text x=\"320\" y=\"182\" text-anchor=\"middle\" font-size=\"14\" fill=\"#2C3548\">Études dans trois ans,</text><text x=\"320\" y=\"204\" text-anchor=\"middle\" font-size=\"14\" fill=\"#2C3548\">travaux sous douze mois</text><text x=\"520\" y=\"158\" text-anchor=\"middle\" font-size=\"15\" font-weight=\"700\" fill=\"#2C3548\">Le reliquat seulement</text><text x=\"520\" y=\"182\" text-anchor=\"middle\" font-size=\"14\" fill=\"#2C3548\">Enveloppes choisies</text><text x=\"520\" y=\"204\" text-anchor=\"middle\" font-size=\"14\" fill=\"#2C3548\">à l’étude, pas avant</text><line x1=\"48\" y1=\"213\" x2=\"192\" y2=\"213\" stroke=\"#8A95A8\" stroke-width=\"2\"/><line x1=\"248\" y1=\"213\" x2=\"392\" y2=\"213\" stroke=\"#8A95A8\" stroke-width=\"2\"/><line x1=\"448\" y1=\"213\" x2=\"592\" y2=\"213\" stroke=\"#8A95A8\" stroke-width=\"2\"/><text x=\"120\" y=\"234\" text-anchor=\"middle\" font-size=\"14\" fill=\"#2C3548\">Constituée en premier</text><text x=\"320\" y=\"234\" text-anchor=\"middle\" font-size=\"14\" fill=\"#2C3548\">Une poche par projet</text><text x=\"520\" y=\"234\" text-anchor=\"middle\" font-size=\"14\" fill=\"#2C3548\">PER, assurance vie, SCPI</text><polygon points=\"212,157 227,169 212,181\" fill=\"#C5A55A\"/><polygon points=\"412,157 427,169 412,181\" fill=\"#C5A55A\"/><text x=\"320\" y=\"286\" text-anchor=\"middle\" font-size=\"14\" fill=\"#8A95A8\">L’horizon d’une poche : la période sans besoin de la somme</text><line x1=\"40\" y1=\"304\" x2=\"586\" y2=\"304\" stroke=\"#8A95A8\" stroke-width=\"2\"/><polygon points=\"586,297 600,304 586,311\" fill=\"#C5A55A\"/><circle cx=\"120\" cy=\"304\" r=\"6\" fill=\"#C5A55A\" stroke=\"#162443\" stroke-width=\"2\"/><circle cx=\"320\" cy=\"304\" r=\"6\" fill=\"#C5A55A\" stroke=\"#162443\" stroke-width=\"2\"/><circle cx=\"520\" cy=\"304\" r=\"6\" fill=\"#C5A55A\" stroke=\"#162443\" stroke-width=\"2\"/><text x=\"120\" y=\"332\" text-anchor=\"middle\" font-size=\"14\" fill=\"#2C3548\">Aujourd’hui</text><text x=\"320\" y=\"332\" text-anchor=\"middle\" font-size=\"14\" fill=\"#2C3548\">À la date du projet</text><text x=\"520\" y=\"332\" text-anchor=\"middle\" font-size=\"14\" fill=\"#2C3548\">Retraite et au delà</text></svg>","legende":"Précaution disponible et sûre d’abord, puis les projets datés, puis le long terme avec le reliquat seulement. L’étude des enveloppes ne porte que sur la troisième poche."},{"cle":"tolerance_capacite","titre":"Tolérance au risque et capacité de perte","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 640 360\" font-family=\"system-ui, -apple-system, Segoe UI, sans-serif\"><title>Tolérance au risque et capacité de perte</title><defs><marker id=\"fleche\" viewBox=\"0 0 10 10\" refX=\"9\" refY=\"5\" markerWidth=\"7\" markerHeight=\"7\" orient=\"auto\"><path d=\"M0,0 L10,5 L0,10 Z\" fill=\"#C5A55A\"/></marker></defs><rect x=\"0\" y=\"0\" width=\"640\" height=\"360\" fill=\"#FFFFFF\"/><text x=\"320\" y=\"32\" text-anchor=\"middle\" font-size=\"20\" font-weight=\"700\" fill=\"#162443\">Tolérance au risque et capacité de perte</text><text x=\"320\" y=\"56\" text-anchor=\"middle\" font-size=\"14\" fill=\"#8A95A8\">Deux informations distinctes, toutes deux obligatoires avant tout conseil</text><rect x=\"30\" y=\"74\" width=\"275\" height=\"140\" rx=\"8\" fill=\"#F5EDD8\" stroke=\"#162443\" stroke-width=\"2\"/><rect x=\"335\" y=\"74\" width=\"275\" height=\"140\" rx=\"8\" fill=\"#F5EDD8\" stroke=\"#162443\" stroke-width=\"2\"/><text x=\"167\" y=\"102\" text-anchor=\"middle\" font-size=\"17\" font-weight=\"700\" fill=\"#162443\">Tolérance au risque</text><text x=\"472\" y=\"102\" text-anchor=\"middle\" font-size=\"17\" font-weight=\"700\" fill=\"#162443\">Capacité à subir des pertes</text><text x=\"167\" y=\"128\" text-anchor=\"middle\" font-size=\"15\" font-weight=\"700\" fill=\"#2C3548\">Ce que le client accepte</text><text x=\"472\" y=\"128\" text-anchor=\"middle\" font-size=\"15\" font-weight=\"700\" fill=\"#2C3548\">Ce que sa situation autorise</text><text x=\"167\" y=\"154\" text-anchor=\"middle\" font-size=\"14\" fill=\"#2C3548\">Se dit en euros et en durée</text><text x=\"167\" y=\"176\" text-anchor=\"middle\" font-size=\"14\" fill=\"#2C3548\">Le vécu prime sur le déclaré</text><text x=\"167\" y=\"198\" text-anchor=\"middle\" font-size=\"14\" fill=\"#2C3548\">Le questionnaire est un support</text><text x=\"472\" y=\"154\" text-anchor=\"middle\" font-size=\"14\" fill=\"#2C3548\">Réserve disponible, échéances</text><text x=\"472\" y=\"176\" text-anchor=\"middle\" font-size=\"14\" fill=\"#2C3548\">Revenus, emprunts, épargne</text><text x=\"472\" y=\"198\" text-anchor=\"middle\" font-size=\"14\" fill=\"#2C3548\">Justificatifs à l’appui</text><line x1=\"167\" y1=\"218\" x2=\"292\" y2=\"248\" stroke=\"#C5A55A\" stroke-width=\"2\" marker-end=\"url(#fleche)\"/><line x1=\"472\" y1=\"218\" x2=\"348\" y2=\"248\" stroke=\"#C5A55A\" stroke-width=\"2\" marker-end=\"url(#fleche)\"/><rect x=\"140\" y=\"252\" width=\"360\" height=\"42\" rx=\"8\" fill=\"#162443\"/><text x=\"320\" y=\"279\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#FFFFFF\">La plus prudente des deux commande</text><text x=\"320\" y=\"322\" text-anchor=\"middle\" font-size=\"14\" fill=\"#2C3548\">Audacieux mais sans réserve : la capacité, plus faible, commande</text><text x=\"320\" y=\"344\" text-anchor=\"middle\" font-size=\"14\" fill=\"#2C3548\">Aisé mais anxieux : la tolérance, plus faible, commande</text></svg>","legende":"La tolérance est ce que le client accepte, la capacité ce que sa situation autorise. Quand elles divergent, la plus prudente des deux commande la recommandation."}]$academy_deck$::jsonb;
  select coalesce(jsonb_agg(s), '[]'::jsonb) into v_conserves
    from jsonb_array_elements(coalesce((select schemas from public.academy_module_versions where id = v_ver), '[]'::jsonb)) s
   where not exists (select 1 from jsonb_array_elements(v_nouveaux) x where x ->> 'cle' = s ->> 'cle');
  update public.academy_module_versions set schemas = v_conserves || v_nouveaux, updated_at = now() where id = v_ver;
  -- Figures : posee sur l exercice existant (ordre, type) qui n en a pas ; au dela du maximum, exercice nouveau.
  select coalesce(max(ordre), 0) into v_max from public.academy_items where version_id = v_ver;
  if v_max >= 5 then
    update public.academy_items set payload = payload || jsonb_build_object('figure', $academy_deck${"ref":"trois_poches"}$academy_deck$::jsonb), updated_at = now()
     where version_id = v_ver and ordre = 5 and type = $academy_deck$choix$academy_deck$ and archive_le is null and not (payload ? 'figure');
  else
    insert into public.academy_items (version_id, ordre, type, competence, difficulte, payload)
    values (v_ver, 5, $academy_deck$choix$academy_deck$, $academy_deck$Liquidité des enveloppes$academy_deck$, 2, $academy_deck${"enonce":"Cas fictif. Monsieur Ibarra dispose de 60 000 euros. Sous douze mois, il prévoit un dépôt de garantie et des travaux estimés à 25 000 euros. Il n'a aucune autre réserve. Quelle organisation est cohérente ?","choix":["Les 60 000 euros sur un PER, pour profiter de la déduction fiscale","Les 60 000 euros en assurance vie sur des unités de compte, rachetables si besoin","Une réserve disponible couvrant les 25 000 euros et une épargne de précaution, le reste seulement engagé dans la durée","Ne rien engager avant la fin des travaux"],"figure":{"ref":"trois_poches"}}$academy_deck$::jsonb)
    returning id into v_item;
    insert into public.academy_items_corriges (item_id, corrige, explication) values (v_item, $academy_deck${"index":2}$academy_deck$::jsonb, $academy_deck$Le besoin à douze mois est connu : le PER est bloqué en principe et des unités de compte peuvent être en perte avant l'échéance.$academy_deck$);
  end if;
  if v_max >= 8 then
    update public.academy_items set payload = payload || jsonb_build_object('figure', $academy_deck${"ref":"tolerance_capacite"}$academy_deck$::jsonb), updated_at = now()
     where version_id = v_ver and ordre = 8 and type = $academy_deck$choix$academy_deck$ and archive_le is null and not (payload ? 'figure');
  else
    insert into public.academy_items (version_id, ordre, type, competence, difficulte, payload)
    values (v_ver, 8, $academy_deck$choix$academy_deck$, $academy_deck$Tolérance et capacité de perte$academy_deck$, 3, $academy_deck${"enonce":"Cas fictif. Madame Nadal se déclare « dynamique ». Elle a vendu ses fonds actions il y a quelques années après une baisse de 25 %. Ses revenus sont élevés et stables, sans échéance particulière. Que consignez-vous ?","choix":["Profil dynamique confirmé par sa situation financière ; l'étude peut porter sur des unités de compte","Un écart entre tolérance déclarée et tolérance observée, à approfondir sur un scénario de baisse avant l'étude","Profil prudent ; l'étude ne portera que sur le fonds en euros","Profil dynamique, avec une part d'unités de compte réduite pour compenser"],"figure":{"ref":"tolerance_capacite"}}$academy_deck$::jsonb)
    returning id into v_item;
    insert into public.academy_items_corriges (item_id, corrige, explication) values (v_item, $academy_deck${"index":1}$academy_deck$::jsonb, $academy_deck$La vente après une baisse contredit le profil déclaré : on consigne l'écart et on le travaille avant toute étude.$academy_deck$);
  end if;
  if v_max >= 9 then
    update public.academy_items set payload = payload || jsonb_build_object('figure', $academy_deck${"ref":"trois_poches"}$academy_deck$::jsonb), updated_at = now()
     where version_id = v_ver and ordre = 9 and type = $academy_deck$choix$academy_deck$ and archive_le is null and not (payload ? 'figure');
  else
    insert into public.academy_items (version_id, ordre, type, competence, difficulte, payload)
    values (v_ver, 9, $academy_deck$choix$academy_deck$, $academy_deck$Liquidité des enveloppes$academy_deck$, 3, $academy_deck${"enonce":"Cas fictif. Madame Lenoir a reçu 70 000 euros. Son associé pourrait lui proposer de racheter ses parts dans dix-huit mois. Elle demande : « On ouvre le PER avec les 70 000 ? » Que répondez-vous ?","choix":["Oui, pour obtenir l'avantage fiscal avant la fin de l'année","Non, définitivement, puisqu'elle n'a jamais détenu d'unités de compte","Ni oui ni non : le PER est bloqué en principe et le rachat de parts n'est pas un cas de déblocage","Oui pour la moitié, l'autre moitié en assurance vie rachetable si besoin"],"figure":{"ref":"trois_poches"}}$academy_deck$::jsonb)
    returning id into v_item;
    insert into public.academy_items_corriges (item_id, corrige, explication) values (v_item, $academy_deck${"index":2}$academy_deck$::jsonb, $academy_deck$Une partie de la somme peut être appelée dans dix-huit mois ; seule la poche long terme sera examinée lors de l'étude, PER compris.$academy_deck$);
  end if;
  if v_max >= 21 then
    update public.academy_items set payload = payload || jsonb_build_object('figure', $academy_deck${"ref":"tolerance_capacite"}$academy_deck$::jsonb), updated_at = now()
     where version_id = v_ver and ordre = 21 and type = $academy_deck$multi$academy_deck$ and archive_le is null and not (payload ? 'figure');
  else
    insert into public.academy_items (version_id, ordre, type, competence, difficulte, payload)
    values (v_ver, 21, $academy_deck$multi$academy_deck$, $academy_deck$Conduite de l'entretien$academy_deck$, 3, $academy_deck${"enonce":"Cas fictif. Madame Lenoir a hérité de 70 000 euros, son compte est juste en fin de mois, elle se dit « pas stressée » mais n'a jamais détenu d'unités de compte, et veut un PER. Cochez tout ce qu'il fallait éviter.","choix":["Ouvrir le PER avec la totalité de la somme","Conclure « profil dynamique » sur une phrase","Citer un plafond de déduction de mémoire","Lui demander une fourchette du rachat auprès de son associé","Constituer d'abord une épargne de précaution"],"figure":{"ref":"tolerance_capacite"}}$academy_deck$::jsonb)
    returning id into v_item;
    insert into public.academy_items_corriges (item_id, corrige, explication) values (v_item, $academy_deck${"indices":[0,1,2]}$academy_deck$::jsonb, $academy_deck$Le plafond se vérifie sur la source officielle, la tolérance s'observe, et une partie de la somme peut être appelée sous dix-huit mois.$academy_deck$);
  end if;
  if v_max >= 41 then
    update public.academy_items set payload = payload || jsonb_build_object('figure', $academy_deck${"ref":"trois_poches"}$academy_deck$::jsonb), updated_at = now()
     where version_id = v_ver and ordre = 41 and type = $academy_deck$choix$academy_deck$ and archive_le is null and not (payload ? 'figure');
  else
    insert into public.academy_items (version_id, ordre, type, competence, difficulte, payload)
    values (v_ver, 41, $academy_deck$choix$academy_deck$, $academy_deck$Situation financière du client$academy_deck$, 2, $academy_deck${"enonce":"Sur le schéma, quelle poche le conseiller examine lors de l’étude pour choisir les enveloppes (PER, assurance vie, SCPI) ?","choix":["La poche 1, précaution : c’est la première constituée","La poche 2, projets datés : chaque projet a sa date","La poche 3, long terme : le reliquat seulement","Les trois poches à la fois, pour diversifier"],"figure":{"ref":"trois_poches"}}$academy_deck$::jsonb)
    returning id into v_item;
    insert into public.academy_items_corriges (item_id, corrige, explication) values (v_item, $academy_deck${"index":2}$academy_deck$::jsonb, $academy_deck$Seule la poche long terme, le reliquat, est examinée lors de l’étude ; la précaution reste disponible et sûre, les projets datés gardent leur date.$academy_deck$);
  end if;
  if v_max >= 42 then
    update public.academy_items set payload = payload || jsonb_build_object('figure', $academy_deck${"ref":"trois_poches"}$academy_deck$::jsonb), updated_at = now()
     where version_id = v_ver and ordre = 42 and type = $academy_deck$multi$academy_deck$ and archive_le is null and not (payload ? 'figure');
  else
    insert into public.academy_items (version_id, ordre, type, competence, difficulte, payload)
    values (v_ver, 42, $academy_deck$multi$academy_deck$, $academy_deck$Situation financière du client$academy_deck$, 1, $academy_deck${"enonce":"Sur le schéma, cochez tout ce qui caractérise la poche 1, l’épargne de précaution.","choix":["Disponible et sûre","Repère AMF de 2 à 6 mois de revenus","Constituée avant les deux autres poches","Bloquée en principe jusqu’à la retraite","Réservée au reliquat, une fois les projets couverts","Placée en unités de compte pour rapporter davantage"],"figure":{"ref":"trois_poches"}}$academy_deck$::jsonb)
    returning id into v_item;
    insert into public.academy_items_corriges (item_id, corrige, explication) values (v_item, $academy_deck${"indices":[0,1,2]}$academy_deck$::jsonb, $academy_deck$La précaution est disponible, sûre, dimensionnée sur le repère AMF et constituée en premier ; le blocage et le reliquat relèvent des autres poches, et une unité de compte peut perdre.$academy_deck$);
  end if;
  if v_max >= 43 then
    update public.academy_items set payload = payload || jsonb_build_object('figure', $academy_deck${"ref":"tolerance_capacite"}$academy_deck$::jsonb), updated_at = now()
     where version_id = v_ver and ordre = 43 and type = $academy_deck$choix$academy_deck$ and archive_le is null and not (payload ? 'figure');
  else
    insert into public.academy_items (version_id, ordre, type, competence, difficulte, payload)
    values (v_ver, 43, $academy_deck$choix$academy_deck$, $academy_deck$Tolérance et capacité de perte$academy_deck$, 2, $academy_deck${"enonce":"Sur le schéma, quel élément relève de la capacité à subir des pertes, et non de la tolérance au risque ?","choix":["L’absence de réserve disponible et deux échéances lourdes dans l’année","La réaction du client lors d’une baisse passée","Ce que le client déclare accepter comme fluctuations","La case « dynamique » cochée dans le questionnaire"],"figure":{"ref":"tolerance_capacite"}}$academy_deck$::jsonb)
    returning id into v_item;
    insert into public.academy_items_corriges (item_id, corrige, explication) values (v_item, $academy_deck${"index":0}$academy_deck$::jsonb, $academy_deck$La capacité se lit dans la situation : réserve, échéances, revenus. La réaction passée, le déclaré et le questionnaire renseignent la tolérance.$academy_deck$);
  end if;
end
$schemas_reussir_la_decouverte$;
